export function CalendarIsland({ month }: { month: string }) {
  const [cells, setCells] = useState<CalendarCell[]>([]);

  useEffect(() => {
    getDays(month).then((d) => setCells(toCells(d)));
  }, [month]);

  return (
    <div data-component="CalendarIsland">
      <CalendarGrid cells={cells} />
    </div>
  );
}

