export function PushToggle() {
  const subscribe = async () => {
    await fetch(`${API_DOMAIN}/push/subscriptions`, { method: 'POST' });
  };

  return (
    <button data-component="PushToggle" onClick={subscribe}>
      通知を有効にする
    </button>
  );
}

export function TodayIsland() {
  const [view, setView] = useState<TodayView | null>(null);

  useEffect(() => {
    getToday().then((t) => setView(toTodayView(t)));
  }, []);

  if (!view) return <p data-component="TodayIsland">読み込み中</p>;
  return (
    <div data-component="TodayIsland">
      <TotalCard view={view} />
      <EntryList entries={view.rows} />
    </div>
  );
}

export function TotalCard({ view }: { view: TodayView }) {
  return (
    <section data-component="TotalCard">
      <h2>今日の合計</h2>
      <p>{view.totalLabel}</p>
    </section>
  );
}

export async function fetcher<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API_DOMAIN}${url}`, init);
  if (!res.ok) {
    throw new Error(`request failed: ${res.status}`);
  }
  return (await res.json()) as T;
}

