export function getDays(month: string): Promise<DailyTotals> {
  return fetcher<DailyTotals>(`/days?month=${month}`);
}

export function toCells(days: DailyTotals): CalendarCell[] {
  return Object.entries(days).map(([date, total]) => ({ date, total }));
}

export function getToday(): Promise<Today> {
  return fetcher<Today>('/today');
}

export function getEntries(): Promise<Entry[]> {
  return fetcher<Entry[]>('/entries');
}

export function createTransaction(body: Entry): Promise<void> {
  return fetcher<void>('/transactions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function toTodayView(today: Today): TodayView {
  return {
    totalLabel: `${today.total.toLocaleString()}円`,
    rows: today.entries,
  };
}
